    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build(vals):
    if not vals or vals[0] == 'null':
        return None
    root = TreeNode(int(vals[0]))
    q, i = [root], 1
    while q and i < len(vals):
        cur = q.pop(0)
        if i < len(vals):
            if vals[i] != 'null':
                cur.left = TreeNode(int(vals[i]))
                q.append(cur.left)
            i += 1
        if i < len(vals):
            if vals[i] != 'null':
                cur.right = TreeNode(int(vals[i]))
                q.append(cur.right)
            i += 1
    return root


def dump(root):
    if root is None:
        return '[]'
    out, q = [], [root]
    while q:
        n = q.pop(0)
        if n is None:
            out.append('null')
        else:
            out.append(str(n.val))
            q.append(n.left)
            q.append(n.right)
    while out and out[-1] == 'null':
        out.pop()
    return '[' + ','.join(out) + ']'


def tokens(s):
    return s.replace('[', ' ').replace(']', ' ').replace(',', ' ').split()


def main():
    lines = [ln for ln in sys.stdin.read().splitlines() if ln.strip()]
    t1 = build(tokens(lines[0]))
    t2 = build(tokens(lines[1])) if len(lines) > 1 else None

    def merge(a, b):
        if not a:
            return b
        if not b:
            return a
        a.val += b.val
        a.left = merge(a.left, b.left)
        a.right = merge(a.right, b.right)
        return a

    print(dump(merge(t1, t2)))


if __name__ == "__main__":
    main()

